-- Extend in place: preserve existing function identity, callers and private permissions.
create or replace function dp_private.validate_room_config(input_config jsonb) returns text[]
language plpgsql set search_path = pg_catalog as $$
declare entries jsonb; ids text[]; approved jsonb;
begin
  entries := input_config->'statements';
  if entries is null or jsonb_typeof(entries) <> 'array' then raise exception 'Invalid practice items'; end if;
  if coalesce(input_config->>'roundSize','3') not in ('3','12')
    or (input_config->>'roundSize'='12' and jsonb_array_length(entries)<>12)
    or jsonb_array_length(entries) < 3 or jsonb_array_length(entries) > 20
    or octet_length(input_config::text) > 20000
    or coalesce(input_config->>'languageId', '') not in ('en', 'no')
    or coalesce(input_config->>'skillId', '') !~ '^[a-z-]{1,80}$'
    or coalesce(input_config->>'caseId', '') !~ '^case-[a-z-]{1,80}$'
    or coalesce(input_config->>'difficulty', '') not in ('easy', 'moderate', 'hard')
    or length(coalesce(input_config->>'contentRevision', '')) not between 1 and 100 then
    raise exception 'Invalid room configuration';
  end if;
  if exists (select 1 from jsonb_array_elements(entries) e where
    coalesce(e->>'id', '') !~ '^[A-Za-z0-9_-]{1,120}$'
    or coalesce(jsonb_typeof(e->'criteriaTags'), '') <> 'array'
    or jsonb_array_length(e->'criteriaTags') > 20) then raise exception 'Invalid practice item'; end if;
  select array_agg(e->>'id') into ids from jsonb_array_elements(entries) e;
  if cardinality(ids) <> (select count(distinct v) from unnest(ids) v) then raise exception 'Duplicate practice item'; end if;
 -- Keep legacy core banks valid while strictly checking these new extension banks.
 if input_config->>'caseId' not in ('case-arne','case-mia','case-nora')
   and not (input_config->>'caseId' in ('case-michael','case-jason','case-laura','case-carlos','case-nina','case-aisha','case-david','case-marcus')
     and input_config->>'skillId' in ('empathic-refocusing','consolidating-emotional-change','closing-after-emotional-work'))
   and input_config->>'skillId'<>'experiential-focusing'
 then return ids; end if;
 select catalog.entries into approved from dp_private.focused_level_catalog catalog
 where catalog.skill_id=input_config->>'skillId' and catalog.case_id=input_config->>'caseId'
   and catalog.difficulty=input_config->>'difficulty' and catalog.revision=input_config->>'contentRevision';
 if approved is null or input_config->>'roundSize' is distinct from '12'
   or coalesce(input_config->>'exerciseType','single-skill')<>'single-skill'
   or input_config->>'exerciseId' is not null
   or jsonb_array_length(input_config->'statements')<>12
   or exists(select 1 from jsonb_array_elements(input_config->'statements') item
     where not exists(select 1 from jsonb_array_elements(approved) expected where expected=item)) then
   raise exception 'Unknown or incompatible practice level. Refresh the app.';
 end if;
 return ids;
end;
$$;
revoke all on function dp_private.validate_room_config(jsonb) from public,anon,authenticated;

-- Permit the new skill in private reminders; keep existing RLS and ownership rules.
alter table public.practice_goals drop constraint practice_goals_skill_id_check;
alter table public.practice_goals add constraint practice_goals_skill_id_check check(skill_id in (
  'therapist-self-awareness','empathic-understanding','empathic-affirmation-validation','exploratory-questions',
  'providing-treatment-rationale','empathic-explorations','empathic-evocations','empathic-conjectures',
  'staying-in-contact-intense-affect','self-disclosure','marker-recognition-chairwork','alliance-repair',
  'empathic-refocusing','consolidating-emotional-change','closing-after-emotional-work','experiential-focusing'));
